"""One accessible interactive experiment per Basic Astrophysics topic."""
def slider(key,label,lo,hi,step,value,unit=''):
    return f'<label for="{key}">{label}{unit}<input id="{key}" type="range" min="{lo}" max="{hi}" step="{step}" value="{value}"></label><output class="range-value" id="range-{key}">{value}</output>'
def select(key,label,options):
    return f'<label for="{key}">{label}<select id="{key}">'+''.join(f'<option value="{v}">{t}</option>' for v,t in options)+'</select></label>'
def shell(key,title,desc,controls,outputs,prompt):
    outs=''.join(f'<div><span>{label}</span><output id="out-{key}-{k}">—</output></div>' for k,label in outputs)
    return f'<section class="cosmo-lab" id="lab-{key}" aria-labelledby="lab-{key}-title"><div class="lab-heading"><span class="lab-kicker">Interactive experiment</span><h3 id="lab-{key}-title">{title}</h3><p>{desc}</p></div><div class="lab-controls">{controls}<button type="button" class="print-btn" data-reset="{key}">Reset experiment</button></div><div class="lab-outputs">{outs}</div><svg class="lab-canvas" id="plot-{key}" viewBox="0 0 680 330" role="img" aria-labelledby="plot-{key}-title"><title id="plot-{key}-title">{title}: interactive vector plot</title></svg><p class="lab-summary" id="summary-{key}" aria-live="polite"></p><div class="lab-prompt"><strong>Try this.</strong> {prompt}</div><p class="print-only lab-print-note">Snapshot of the experiment. Open the HTML edition to change the controls.</p><noscript><p class="lab-noscript">Enable JavaScript to use the experiment. The lecture and problems remain readable.</p></noscript></section>'
def orbit():
    c=slider('orbit-a','Semimajor axis',.4,5,.1,1,' [AU]')+slider('orbit-e','Eccentricity',0,.85,.01,.6)+slider('orbit-m','Total mass',.5,5,.1,1,' [M☉]')+'<button type="button" class="print-btn" id="orbit-play">Pause orbit</button>'
    return shell('orbit','Change the orbit, not the conservation laws.','Relative two-body orbit in AU, solar masses and years. The primary is placed at a focus; the plotted path is the separation vector’s orbit. Sizes are symbolic.',c,[('period','Period'),('rp','Periapsis'),('ra','Apoapsis'),('vp','Periapsis speed'),('va','Apoapsis speed'),('energy','Specific relative energy')],'Double the semimajor axis at fixed mass. By what factor does the period change? At fixed semimajor axis, increase eccentricity: does the period change?')
def blackbody():
    c=slider('bb-t','Temperature',2500,12000,50,5800,' [K]')+slider('bb-r','Radius',.2,3,.05,1,' [R☉]')
    return shell('blackbody','A hotter surface is bluer—and much brighter.','Planck wavelength spectra, normalized separately for the selected star and the 5772 K reference. Radius changes luminosity but not the spectral peak.',c,[('peak','Wien peak'),('flux','Surface flux'),('lum','Luminosity'),('photon','hc/λ_peak')],'Double the temperature. The peak wavelength halves, but the surface flux grows sixteenfold. Then double the radius at fixed temperature.')
def gas():
    c=select('gas-process','Process',[('isothermal','Isothermal'),('isobaric','Isobaric'),('isochoric','Isochoric'),('adiabatic','Reversible adiabatic')])+slider('gas-r','Volume ratio (pressure ratio if isochoric)',1,4,.05,2)
    return shell('gas','Same starting state. Different energy bills.','One mole of monatomic ideal gas starts at 300 K and 100 kPa. The slider sets V₂/V₁, except for the isochoric process where it sets P₂/P₁. W is work done by the gas; Q = ΔU + W.',c,[('state','Final T'),('pressure','Final P'),('work','Work W'),('heat','Heat Q'),('internal','ΔU'),('volume','Final V')],'Compare isothermal and adiabatic expansion to twice the volume. Which needs heat input? Which cools? Check every result against the first law.')
def spectrum():
    c=select('spec-line','Rest line',[('656.28','Hα · 656.28 nm'),('486.13','Hβ · 486.13 nm'),('589.0','Na D · 589.0 nm')])+slider('spec-v','Receding velocity',-1000,1000,5,100,' [km/s]')+slider('spec-t','Gas temperature',3000,30000,100,10000,' [K]')+slider('spec-r','Resolving power λ/Δλ',1000,100000,1000,20000)
    return shell('spectrum','Separate a line’s position from its width.','Thermal broadening (H atoms for hydrogen lines, Na atoms for Na D) plus a Gaussian instrumental profile. The relativistic radial Doppler formula sets the centre. Other broadening mechanisms are neglected.',c,[('lambda','Observed centre'),('shift','Shift Δλ'),('thermal','Thermal FWHM'),('instrument','Instrument FWHM'),('total','Combined FWHM'),('velocity','Thermal σᵥ')],'Set velocity to zero: the line still has a width. Increase resolving power: does the physical thermal width change? Compare a blue shift with a red shift.')
def decay():
    c=select('decay-isotope','Isotope',[('c14','Carbon-14 · 5730 yr'),('i131','Iodine-131 · 8.02 d'),('co60','Cobalt-60 · 5.27 yr')])+slider('decay-n','Elapsed half-lives',0,8,.05,1)
    return shell('decay','A clock made from a probability law.','Start with 10¹² radioactive nuclei. The surviving number and activity decay together. The isotope changes the real-time scale, not the shape when time is measured in half-lives.',c,[('remaining','Nuclei remaining'),('fraction','Surviving fraction'),('activity','Activity'),('elapsed','Elapsed time'),('lambda','Decay constant'),('mean','Mean lifetime')],'After three half-lives, one eighth remains—not zero. Switch isotope at the same number of half-lives and compare the activities.')
LABS={'orbit':orbit,'blackbody':blackbody,'gas':gas,'spectrum':spectrum,'decay':decay}
